import json
data = json.loads(input_data)
catype = ""
lnumber = ""
areaCode = "Plan"
for p in data['hasPart']:
    if p['type'] == 'wa-name-part-type:crownAreaCode':
      if 'ref' in p:
        areaCode = p['ref'].split(":")[1].title()
      else:
        areaCode = "Not Defined"
    elif  p['type'] == 'wa-name-part-type:crownAllocationType':
      catype = "Town Lot"
    elif  p['type'] == 'wa-name-part-type:number':
      lnumber = p['label']
output_data=f"{areaCode} {catype} {lnumber}"

